#include <map>
using namespace std;

vector<char> a = {'L', 'I', 'T'};

int main() {
    int t; cin >> t;
    while (t--) {
        int n; cin >> n;
        string s; cin >> s;
        set<char> se;
        for (auto u : s) se.insert(u);
        if (se.size() == 1) {
            cout << -1 << endl;
            continue;
        }
        vector<int> ans;
        map<char, int> mp;
        for (auto u : s) {
            mp[u]++;
        }
        auto func = [&](int i) {
            for (auto u : a) {
                if (s[i] != u && s[i + 1] != u) return u;
            }
            return '$';
        };
        while (max({mp['L'], mp['I'], mp['T']}) != min({mp['L'], mp['I'], mp['T']})) {
            int mn = min({mp['L'], mp['I'], mp['T']});
            int mx = max({mp['L'], mp['I'], mp['T']});
            int ok = 0;
            for (int i = 0; i < s.size() - 1; i++) {
                char x = func(i);
                if (s[i] != s[i + 1] && mp[x] == mn) {
                    mp[x]++;
                    ok = 1;
                    s.insert(s.begin() + i + 1, x);
                    ans.push_back(i);
                    break;
                }
            }
            if (!ok) {
                for (int i = 0; i < s.size() - 1; i++) {
                    char x = func(i);
                    if (s[i] != s[i + 1] && mp[x] == mx) {
                        mp[x]++;
                        s.insert(s.begin() + i + 1, x);
                        ans.push_back(i);
                        ok = 1;
                        break;
                    }
                }
            }
        }
        cout << ans.size() << endl;
        for (auto u : ans) {
            cout << u + 1 << endl;
        }
    }
}

